from sqlalchemy.orm import Session
from backend.services.skill_registry import SkillRegistry

class AgentManager:
    def __init__(self, db: Session):
        self.db = db
        self.skill_registry = SkillRegistry()

    def execute_skill(self, skill_name: str, params: dict) -> dict:
        return self.skill_registry.execute(skill_name, params)

class SkillRegistry:
    def __init__(self):
        self._skills = {}

    def register(self, name: str, skill_func):
        self._skills[name] = skill_func

    def execute(self, name: str, params: dict) -> dict:
        skill = self._skills.get(name)
        if not skill:
            return {"error": f"Skill {name} not found"}
        return skill(params)

