const API_BASE_URL = process.env.REACT_APP_API_URL || "http://localhost:8000/api";

export async function createProject(name: string, requirements: string): Promise<any> {
  const response = await fetch(`${API_BASE_URL}/projects`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ name, requirements }),
  });
  return response.json();
}

export async function getProject(projectId: string): Promise<any> {
  const response = await fetch(`${API_BASE_URL}/projects/${projectId}`);
  return response.json();
}

export async function assignRoles(projectId: string, roles: Array<{ role_name: string; user_id: string }>): Promise<any> {
  const response = await fetch(`${API_BASE_URL}/projects/${projectId}/roles`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ roles }),
  });
  return response.json();
}

export async function confirmPRD(projectId: string): Promise<any> {
  const response = await fetch(`${API_BASE_URL}/projects/${projectId}/confirm-prd`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
  });
  return response.json();
}

export async function getArtifacts(projectId: string): Promise<any> {
  const response = await fetch(`${API_BASE_URL}/projects/${projectId}/artifacts`);
  return response.json();
}

export async function getTestCases(projectId: string): Promise<any> {
  const response = await fetch(`${API_BASE_URL}/projects/${projectId}/tests`);
  return response.json();
}

export async function getBugs(projectId: string): Promise<any> {
  const response = await fetch(`${API_BASE_URL}/projects/${projectId}/tests/bugs`);
  return response.json();
}

export async function getAuditLogs(projectId: string): Promise<any> {
  const response = await fetch(`${API_BASE_URL}/projects/${projectId}/audit-logs`);
  return response.json();
}

import React from "react";
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import Home from "../pages/Home";
import ProjectPage from "../pages/ProjectPage";

const App: React.FC = () => {
  return (
    <Router>
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/project/:projectId" element={<ProjectPage />} />
      </Routes>
    </Router>
  );
};

export default App;

import React, { useEffect, useState } from "react";
import { getProject } from "../api/client";

interface DashboardProps {
  projectId: string;
}

const Dashboard: React.FC<DashboardProps> = ({ projectId }) => {
  const [project, setProject] = useState<any>(null);

  useEffect(() => {
    getProject(projectId).then(setProject).catch(console.error);
  }, [projectId]);

  if (!project) return <div>Loading...</div>;

  return (
    <div>
      <h2>Project Dashboard</h2>
      <p>Name: {project.name}</p>
      <p>Status: {project.status}</p>
      <p>Test Pass Rate: {project.test_pass_rate}%</p>
    </div>
  );
};

export default Dashboard;

import React, { useState } from "react";
import { createProject, confirmPRD } from "../api/client";

interface ChatInterfaceProps {
  onProjectCreated: (projectId: string) => void;
}

const ChatInterface: React.FC<ChatInterfaceProps> = ({ onProjectCreated }) => {
  const [messages, setMessages] = useState<Array<{ role: string; content: string }>>([]);
  const [input, setInput] = useState("");

  const sendMessage = async () => {
    if (!input.trim()) return;
    const userMessage = { role: "user", content: input };
    setMessages((prev) => [...prev, userMessage]);
    setInput("");

    try {
      const project = await createProject("New Project", input);
      const botMessage = { role: "bot", content: `Project created with ID: ${project.project_id}` };
      setMessages((prev) => [...prev, botMessage]);
      onProjectCreated(project.project_id);
    } catch (error) {
      const botMessage = { role: "bot", content: "Error creating project" };
      setMessages((prev) => [...prev, botMessage]);
    }
  };

  return (
    <div>
      <div>
        {messages.map((msg, idx) => (
          <div key={idx} style={{ fontWeight: msg.role === "user" ? "bold" : "normal" }}>
            {msg.role}: {msg.content}
          </div>
        ))}
      </div>
      <input value={input} onChange={(e) => setInput(e.target.value)} placeholder="Enter requirements..." />
      <button onClick={sendMessage}>Send</button>
    </div>
  );
};

export default ChatInterface;

import React, { useState } from "react";
import { assignRoles } from "../api/client";

interface RoleSelectorProps {
  projectId: string;
}

const RoleSelector: React.FC<RoleSelectorProps> = ({ projectId }) => {
  const [roles, setRoles] = useState<Array<{ role_name: string; user_id: string }>>([]);
  const [roleName, setRoleName] = useState("");
  const [userId, setUserId] = useState("");

  const addRole = () => {
    if (!roleName || !userId) return;
    setRoles((prev) => [...prev, { role_name: roleName, user_id: userId }]);
    setRoleName("");
    setUserId("");
  };

  const submitRoles = async () => {
    try {
      await assignRoles(projectId, roles);
      alert("Roles assigned successfully");
    } catch (error) {
      alert("Error assigning roles");
    }
  };

  return (
    <div>
      <h3>Role Selector</h3>
      <input value={roleName} onChange={(e) => setRoleName(e.target.value)} placeholder="Role name (e.g., PM)" />
      <input value={userId} onChange={(e) => setUserId(e.target.value)} placeholder="User ID" />
      <button onClick={addRole}>Add Role</button>
      <ul>
        {roles.map((role, idx) => (
          <li key={idx}>{role.role_name} - {role.user_id}</li>
        ))}
      </ul>
      <button onClick={submitRoles}>Submit Roles</button>
    </div>
  );
};

export default RoleSelector;

import React, { useEffect, useState } from "react";
import { getArtifacts } from "../api/client";

interface ArtifactViewerProps {
  projectId: string;
}

const ArtifactViewer: React.FC<ArtifactViewerProps> = ({ projectId }) => {
  const [artifacts, setArtifacts] = useState<any[]>([]);

  useEffect(() => {
    getArtifacts(projectId).then(setArtifacts).catch(console.error);
  }, [projectId]);

  return (
    <div>
      <h3>Artifacts</h3>
      {artifacts.length === 0 ? (
        <p>No artifacts yet.</p>
      ) : (
        <ul>
          {artifacts.map((artifact) => (
            <li key={artifact.id}>
              <strong>{artifact.type}</strong> (v{artifact.version}) - {artifact.created_by}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default ArtifactViewer;

import React, { useEffect, useState } from "react";
import { getTestCases, getBugs } from "../api/client";

interface TestReportProps {
  projectId: string;
}

const TestReport: React.FC<TestReportProps> = ({ projectId }) => {
  const [testCases, setTestCases] = useState<any[]>([]);
  const [bugs, setBugs] = useState<any[]>([]);

  useEffect(() => {
    getTestCases(projectId).then(setTestCases).catch(console.error);
    getBugs(projectId).then(setBugs).catch(console.error);
  }, [projectId]);

  return (
    <div>
      <h3>Test Report</h3>
      <h4>Test Cases ({testCases.length})</h4>
      <ul>
        {testCases.map((tc) => (
          <li key={tc.id}>{tc.description} - {tc.status}</li>
        ))}
      </ul>
      <h4>Bugs ({bugs.length})</h4>
      <ul>
        {bugs.map((bug) => (
          <li key={bug.id}>{bug.description} - {bug.status}</li>
        ))}
      </ul>
    </div>
  );
};

export default TestReport;

